INSERT INTO "movie_translations" ("movie_id", "language_code", "title", "description", "created_at", "updated_at") VALUES ('01a08b08-0b8c-7585-b65e-526417f35c33', 'vi', 'Dune: Hành Tinh Cát - Phần Hai', 'Paul Atreides hợp lực cùng Chani và người Fremen trên con đường tìm kiếm sự báo thù chống lại những kẻ đã hủy hoại gia tộc mình.', '2026-09-10T11:15:55.489Z', '2026-09-10T11:15:55.489Z') ON CONFLICT DO NOTHING;
