INSERT INTO "movie_translations" ("movie_id", "language_code", "title", "description", "created_at", "updated_at") VALUES ('01a08b08-0caa-72d5-ab36-a8d7bc2613b8', 'vi', 'Oppenheimer', 'Câu chuyện lịch sử về nhà vật lý lý thuyết J. Robert Oppenheimer, người lãnh đạo Dự án Manhattan phát triển vũ khí hạt nhân đầu tiên.', '2026-09-10T11:15:55.770Z', '2026-09-10T11:15:55.770Z') ON CONFLICT DO NOTHING;
