INSERT INTO "movie_translations" ("movie_id", "language_code", "title", "description", "created_at", "updated_at") VALUES ('01a08b08-0dbc-7085-afba-ee90dd30d489', 'vi', 'Deadpool & Wolverine', 'Wade Wilson vô tình bị kéo vào nhiệm vụ giải cứu đa vũ trụ cùng với một biến thể Wolverine mang đầy tổn thương.', '2026-09-10T11:15:56.046Z', '2026-09-10T11:15:56.046Z') ON CONFLICT DO NOTHING;
